Below is a **complete, runnable mini-ORM** built on top of `sqlite3`. It demonstrates the core ORM concepts from scratch:

- model classes ↔ tables  
- field/column descriptors  
- primary keys and auto-increment  
- create table  
- insert / update / delete  
- queries with filtering, ordering, limits  
- lazy relationships (`belongs_to`, `has_many`)

Save it as `mini_orm.py` and run it with `python mini_orm.py`.

```python
import sqlite3
import sys
from typing import Any, Optional


# --------------------------------------------------------------------------- #
# Registry so string references ("Author", "Post") can be resolved at runtime
# --------------------------------------------------------------------------- #
_MODEL_REGISTRY: dict[str, type] = {}


# --------------------------------------------------------------------------- #
# Helpers
# --------------------------------------------------------------------------- #
_MISSING = object()

_SQLITE_TYPES = {int: "INTEGER", str: "TEXT", float: "REAL", bool: "INTEGER", bytes: "BLOB"}


def _sql_type(t):
    if isinstance(t, str):
        return t
    return _SQLITE_TYPES.get(t, "TEXT")


def _resolve_model(ref):
    if isinstance(ref, type):
        return ref
    if ref in _MODEL_REGISTRY:
        return _MODEL_REGISTRY[ref]
    raise RuntimeError(f"Model {ref!r} is not registered")


# --------------------------------------------------------------------------- #
# Column descriptor
# --------------------------------------------------------------------------- #
class Column:
    def __init__(self, type_, *, primary_key=False, nullable=True, default=None,
                 unique=False, foreign_key=None):
        self.type = type_
        self.primary_key = primary_key
        self.nullable = nullable
        self.default = default
        self.unique = unique
        self.foreign_key = foreign_key
        self.name = None

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return instance.__dict__.get(self.name, self.default)

    def __set__(self, instance, value):
        instance.__dict__[self.name] = value

    def __repr__(self):
        return f"Column({self.name!r}, {self.type})"


# --------------------------------------------------------------------------- #
# Relationships (lazy loading)
# --------------------------------------------------------------------------- #
class _Relationship:
    def __init__(self, target, fk):
        self.target = target
        self.fk = fk
        self.cache_attr = None

    def _target(self):
        return _resolve_model(self.target)

    def _target_pk(self):
        return self._target()._pk_column()


class BelongsTo(_Relationship):
    def __set_name__(self, owner, name):
        self.cache_attr = f"_rel_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if self.cache_attr in instance.__dict__:
            return instance.__dict__[self.cache_attr]

        db = instance._db or _DEFAULT_DB
        target = self._target()
        fk_val = getattr(instance, self.fk, None)
        value = target.get(db, fk_val) if (db is not None and fk_val is not None) else None
        instance.__dict__[self.cache_attr] = value
        return value

    def __set__(self, instance, value):
        instance.__dict__[self.cache_attr] = value
        target = self._target()
        pk_name = target._pk_column()
        setattr(instance, self.fk, getattr(value, pk_name) if value is not None else None)


class HasMany(_Relationship):
    def __set_name__(self, owner, name):
        self.cache_attr = f"_rel_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if self.cache_attr in instance.__dict__:
            return instance.__dict__[self.cache_attr]

        db = instance._db or _DEFAULT_DB
        target = self._target()
        pk_val = getattr(instance, owner._pk_column(), None)
        if db is None or pk_val is None:
            items = []
        else:
            items = target.query(db).filter(**{self.fk: pk_val}).all()
        instance.__dict__[self.cache_attr] = items
        return items


# --------------------------------------------------------------------------- #
# Database / engine
# --------------------------------------------------------------------------- #
class Database:
    def __init__(self, path=":memory:"):
        self.path = path
        self.conn = sqlite3.connect(path, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row

    def execute(self, sql, params=()):
        cur = self.conn.cursor()
        cur.execute(sql, params)
        self.conn.commit()
        return cur

    def close(self):
        self.conn.close()


_DEFAULT_DB: Optional[Database] = None


def set_default_db(db: Database):
    global _DEFAULT_DB
    _DEFAULT_DB = db


# --------------------------------------------------------------------------- #
# Query builder
# --------------------------------------------------------------------------- #
class Query:
    _OP = {"eq": "=", "ne": "!=", "gt": ">", "gte": ">=",
           "lt": "<", "lte": "<=", "like": "LIKE"}

    def __init__(self, model, db):
        self.model = model
        self.db = db
        self._conditions = []
        self._order = None
        self._limit = None
        self._offset = None

    def filter(self, **kwargs):
        for key, value in kwargs.items():
            if "__" in key:
                field, op = key.rsplit("__", 1)
                if op not in self._OP and op != "in":
                    field, op = key, "eq"
            else:
                field, op = key, "eq"

            if field not in self.model._columns:
                raise ValueError(f"Unknown field {field!r} on {self.model.__name__}")
            self._conditions.append((field, op, value))
        return self

    def order_by(self, *fields):
        parts = []
        for f in fields:
            if f.startswith("-"):
                parts.append(f[1:] + " DESC")
            else:
                parts.append(f + " ASC")
        self._order = ", ".join(parts)
        return self

    def limit(self, n):
        self._limit = int(n)
        return self

    def offset(self, n):
        self._offset = int(n)
        return self

    def _build(self):
        sql = f"SELECT * FROM {self.model._table_name}"
        params = []

        if self._conditions:
            clauses = []
            for field, op, value in self._conditions:
                if op == "in":
                    placeholders = ", ".join("?" for _ in value)
                    clauses.append(f"{field} IN ({placeholders})")
                    params.extend(value)
                else:
                    if op not in self._OP:
                        raise ValueError(f"Unknown operator {op!r}")
                    clauses.append(f"{field} {self._OP[op]} ?")
                    params.append(value)
            sql += " WHERE " + " AND ".join(clauses)

        if self._order:
            sql += " ORDER BY " + self._order
        if self._limit is not None:
            sql += " LIMIT ?"
            params.append(self._limit)
        if self._offset is not None:
            sql += " OFFSET ?"
            params.append(self._offset)

        return sql, params

    def all(self):
        if self.db is None:
            raise RuntimeError("No database available")
        sql, params = self._build()
        cur = self.db.execute(sql, params)
        return [self.model._from_row(r, self.db) for r in cur.fetchall()]

    def first(self):
        self.limit(1)
        rows = self.all()
        return rows[0] if rows else None

    def count(self):
        if self.db is None:
            raise RuntimeError("No database available")
        sql = f"SELECT COUNT(*) AS c FROM {self.model._table_name}"
        params = []
        if self._conditions:
            clauses = []
            for field, op, value in self._conditions:
                if op == "in":
                    placeholders = ", ".join("?" for _ in value)
                    clauses.append(f"{field} IN ({placeholders})")
                    params.extend(value)
                else:
                    clauses.append(f"{field} {self._OP[op]} ?")
                    params.append(value)
            sql += " WHERE " + " AND ".join(clauses)
        cur = self.db.execute(sql, params)
        return cur.fetchone()["c"]


# --------------------------------------------------------------------------- #
# Metaclass
# --------------------------------------------------------------------------- #
class ModelMeta(type):
    def __new__(mcs, name, bases, namespace):
        if name == "Model":
            return super().__new__(mcs, name, bases, namespace)

        # inherit columns from bases
        columns = {}
        for base in bases:
            if hasattr(base, "_columns"):
                for k, v in base._columns.items():
                    if k not in columns:
                        columns[k] = v

        # collect new columns
        for key, val in list(namespace.items()):
            if isinstance(val, Column):
                columns[key] = val

        namespace["_columns"] = columns
        namespace["_table_name"] = namespace.get("__tablename__", name.lower() + "s")

        cls = super().__new__(mcs, name, bases, namespace)
        _MODEL_REGISTRY[name] = cls
        return cls


# --------------------------------------------------------------------------- #
# Base Model
# --------------------------------------------------------------------------- #
class Model(metaclass=ModelMeta):
    _columns = {}
    _table_name = ""
    _persisted = False
    _db = None

    def __init__(self, **kwargs):
        self._persisted = False
        self._db = kwargs.pop("_db", None)

        # defaults
        for name, col in type(self)._columns.items():
            if col.default is not None:
                setattr(self, name, col.default)

        for key, value in kwargs.items():
            setattr(self, key, value)

    # ---- helpers ----
    @classmethod
    def _pk_column(cls):
        for name, col in cls._columns.items():
            if getattr(col, "primary_key", False):
                return name
        if "id" in cls._columns:
            return "id"
        return None

    # ---- schema ----
    @classmethod
    def create_table(cls, db: Database):
        lines = []
        for name, col in cls._columns.items():
            line = f"{name} {_sql_type(col.type)}"
            if col.primary_key:
                line += " PRIMARY KEY"
            if not col.nullable and not col.primary_key:
                line += " NOT NULL"
            if col.unique:
                line += " UNIQUE"
            if col.foreign_key:
                fk = col.foreign_key
                # allow "authors.id" or "authors(id)"
                if "." in fk and "(" not in fk:
                    table, column = fk.split(".", 1)
                    fk = f"{table}({column})"
                line += f" REFERENCES {fk}"
            lines.append(line)

        sql = (
            f"CREATE TABLE IF NOT EXISTS {cls._table_name} (\n  "
            + ",\n  ".join(lines)
            + "\n)"
        )
        db.execute(sql)

    # ---- query entry points ----
    @classmethod
    def query(cls, db=None):
        db = db or _DEFAULT_DB
        return Query(cls, db)

    @classmethod
    def get(cls, db, pk):
        if db is None or pk is None:
            return None
        return cls.query(db).filter(**{cls._pk_column(): pk}).first()

    @classmethod
    def all(cls, db=None):
        return cls.query(db).all()

    # ---- hydration ----
    @classmethod
    def _from_row(cls, row, db=None):
        instance = cls()
        for name in cls._columns:
            setattr(instance, name, row[name])
        instance._persisted = True
        instance._db = db
        return instance

    # ---- persistence ----
    def save(self, db=None):
        db = db or self._db or _DEFAULT_DB
        if db is None:
            raise RuntimeError("No database available")
        self._db = db

        cls = type(self)
        table = cls._table_name
        pk_name = cls._pk_column()
        columns = list(cls._columns.keys())

        # UPDATE path
        if self._persisted and pk_name and getattr(self, pk_name) is not None:
            fields = [c for c in columns if c != pk_name]
            if fields:
                set_clause = ", ".join(f"{c}=?" for c in fields)
                params = [getattr(self, c) for c in fields] + [getattr(self, pk_name)]
                db.execute(f"UPDATE {table} SET {set_clause} WHERE {pk_name}=?", params)
        else:
            # INSERT path (omit auto PK if not provided)
            pk_val = getattr(self, pk_name) if pk_name else None
            insert_cols = [c for c in columns if not (c == pk_name and pk_val is None)]
            placeholders = ", ".join("?" for _ in insert_cols)
            params = [getattr(self, c) for c in insert_cols]
            cur = db.execute(
                f"INSERT INTO {table} ({', '.join(insert_cols)}) VALUES ({placeholders})",
                params,
            )
            if pk_name and pk_val is None:
                setattr(self, pk_name, cur.lastrowid)
            self._persisted = True

        # invalidate cached relationships
        for key in list(self.__dict__.keys()):
            if key.startswith("_rel_"):
                del self.__dict__[key]

        return self

    def delete(self, db=None):
        db = db or self._db or _DEFAULT_DB
        if db is None:
            raise RuntimeError("No database available")
        self._db = db

        cls = type(self)
        if not self._persisted:
            return

        pk_name = cls._pk_column()
        if pk_name and getattr(self, pk_name) is not None:
            db.execute(
                f"DELETE FROM {cls._table_name} WHERE {pk_name}=?",
                (getattr(self, pk_name),),
            )
        self._persisted = False

    def __repr__(self):
        cls = type(self)
        pk_name = cls._pk_column()
        pk_val = getattr(self, pk_name) if pk_name else None
        return f"{cls.__name__}(pk={pk_val!r})"


# --------------------------------------------------------------------------- #
# Demo
# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    db = Database(":memory:")
    set_default_db(db)

    class Author(Model):
        __tablename__ = "authors"
        id = Column(int, primary_key=True)
        name = Column(str, nullable=False)
        posts = HasMany("Post", "author_id")

    class Post(Model):
        __tablename__ = "posts"
        id = Column(int, primary_key=True)
        title = Column(str, nullable=False)
        body = Column(str, default="")
        author_id = Column(int, foreign_key="authors.id")
        author = BelongsTo("Author", "author_id")

    # schema
    Author.create_table(db)
    Post.create_table(db)

    # insert
    alice = Author(name="Alice").save()
    bob = Author(name="Bob").save()

    p1 = Post(title="Hello", body="first post", author=alice).save()
    p2 = Post(title="Second", author_id=bob.id).save()

    print("Authors:", [a.name for a in Author.query(db).all()])

    print("\nPosts (newest first):")
    for p in Post.query(db).order_by("-id").all():
        author_name = p.author.name if p.author else None
        print(f"  {p.id}: {p.title!r} -> {author_name}")

    # relationship helpers
    print("\nAlice's posts:", [p.title for p in alice.posts])
    print("Posts by Bob:", [p.title for p in Post.query(db).filter(author_id=bob.id).all()])

    # filtering operators
    print("\nTitles starting with 'H':",
          [p.title for p in Post.query(db).filter(title__like="H%").all()])

    # update
    p1.title = "Hello, updated"
    p1.save()
    print("\nAfter update:", Post.get(db, p1.id).title)

    # delete
    p2.delete()
    print("Post count after delete:", Post.query(db).count())

    db.close()
```

## How the pieces work

- **`Column`** is a descriptor. Reading/writing `author.name` actually stores the value in the instance `__dict__`, while the `Column` object (stored on the class) keeps schema metadata such as SQL type, nullability, and foreign keys.
- **`ModelMeta`** scans a model class body for `Column` instances and builds `_columns`. It also registers every model by name so `BelongsTo("Author")` / `HasMany("Post")` can be resolved lazily.
- **`Model`** provides the shared persistence logic:
  - `create_table()` translates Python types into SQLite column definitions.
  - `save()` does an `INSERT` (omitting a missing auto primary key so SQLite assigns one) or an `UPDATE` when the row already exists.
  - `delete()` removes by primary key.
- **`Query`** builds SQL incrementally. `filter()` supports equality and operators like `title__like`, `id__gt`, `id__in`, ordering with `order_by("-id")`, and `limit`/`offset`.
- **Relationships** are lazy:
  - `BelongsTo` loads the related object on first access and keeps the foreign key in sync when assigned.
  - `HasMany` runs a filtered query when first accessed.
- **`Database`** wraps a `sqlite3` connection. A module-level default database can be set with `set_default_db()`, which keeps the demo code concise.

### Extending it

This is intentionally small. Natural next steps for a production ORM would be: migrations, transactions/contexts, connection pooling, eager loading, caching invalidation across relationships, schema constraints/indexes, and support for multiple backends. But the example above already captures the basic ORM workflow end to end.
